let MAX_N = CAP0_N, MAX_E = CAP0_E;      /* 当前容量（会增长） */

let nPos = new Float32Array(MAX_N * 3);
let nAct = new Uint8Array(MAX_N);
let nBias = new Float32Array(MAX_N);
let nLock = new Uint8Array(MAX_N);      // 1 = 冻结（不参与训练）
let nIO = new Uint8Array(MAX_N);        // 接口标记（IO_* 位或）
let nCol = new Float32Array(MAX_N * 3); // 自定义颜色 RGB 0..1，仅在 nColOn 时生效
let nColOn = new Uint8Array(MAX_N);     // 1 = 用自定义颜色，0 = 用接口色 / 默认色
let nThr = new Float32Array(MAX_N);     // 激活阈值（模拟激活用）
let nPlast = new Uint8Array(MAX_N);      // 可塑性档位号（0 = 固定不学；档位表见 PLAST.list）
let nHard = new Uint8Array(MAX_N);       // 1 = 强硬抑制型：它一活，下游这一拍直接不让激活
/* 「强硬压制」和「负权重」是两回事，别混：
   负权重是把加权和拉低，目标只要别的兴奋够多照样能过阈值；
   强硬压制是直接把目标的这一拍摁掉，跟它收到多少兴奋无关——
   生物里那种"抑制神经元一放电，后面的就别想动"就是这种。 */
/* 名称表：不是一个大 Map，而是按神经元索引切成固定段的小 Map（跟那 16 列一个思路）。
   段号 = 索引 >> NAME_SHIFT，每段 1024 个神经元；没起过名字的段是 undefined，一个字节都不占。
   段对象会被撤销快照直接引用（跟块一样），所以写之前先看 shared：共享中的段先克隆一份私有的。
   对外方法名跟 Map 一样（get / set / delete / has / clear / forEach / 迭代器），
   所以原来读这张表的 30 处代码一行都不用改。 */
const NAME_SHIFT = 10;
const NAME_SEG = 1 << NAME_SHIFT;
