  get(i) { const s = nNameSegs[i >> NAME_SHIFT]; return s ? s.m.get(i) : undefined; },
  has(i) { const s = nNameSegs[i >> NAME_SHIFT]; return !!s && s.m.has(i); },
  set(i, v) { nameSegWritable(i >> NAME_SHIFT).set(i, v); return nName; },
