  forEach(cb, thisArg) { for (let k = 0; k < nNameSegs.length; k++) { const s = nNameSegs[k]; if (s) s.m.forEach(cb, thisArg); } },
  *[Symbol.iterator]() { for (let k = 0; k < nNameSegs.length; k++) { const s = nNameSegs[k]; if (s) for (const e of s.m) yield e; } },
