  for (let k = 0; k < ee.length && k < HID_MAX; k++) { const e = ee[k]; if (e >= 0 && e < G.e && eHid[e] !== (on ? 1 : 0)) { eHid[e] = on ? 1 : 0; histEdgeDirty = 1; ce++; } }
