  for (let k = 0; k < nNameSegs.length; k++) { const sg = nNameSegs[k]; if (sg) naive += nameSegBytes(sg.m); }
  return { steps: history.stack.length, head: history.head, limit: history.limit,
           uniqueChunks: seen.size + seenB.size + seenN.size, chunks: chunks + blkChunks + nameSegs,
           bytes: bytes + blkBytes + nameBytes, blkBytes, blkChunks, nameBytes, nameSegs,
           nameSegsUnique: seenN.size, naive, perCol };
