function opDtypeOf(code) { for (let i = 0; i < OP_DTYPES.length; i++) if (OP_DTYPES[i].code === code) return OP_DTYPES[i]; return null; }
function opDtypeByName(nm) { for (let i = 0; i < OP_DTYPES.length; i++) if (OP_DTYPES[i].name === nm) return OP_DTYPES[i]; return null; }
