    attrs: Object.assign({}, opt.attrs || {}),
    /* 折进来的逐元素算子（ReLU / BatchNorm 这类"不新的算子节点也能表达"的那些） */
    fold: (opt.fold || []).slice(),
    params: params,
    note: String(opt.note || ''),
    /* 颜色：0 = 用类型默认色，>0 时按 ORB 顺序取（跟神经元同一套色板） */
    color: (opt.color | 0), colOn: opt.colOn ? 1 : 0,
    /* 显示位置。null = 摆在落点神经元 / 输入神经元的重心上 */
    pos: opt.pos ? { x: +opt.pos.x || 0, y: +opt.pos.y || 0, z: +opt.pos.z || 0 } : null,
