  const del = ids instanceof Set ? ids : new Set(ids);
  for (const id of del) {
    const dep = opDependents(id).filter((x) => !del.has(x));
    if (dep.length) {
      return { ok: false, deleted: 0, msg: '算子 #' + id + '（' + opNameOf(id) + '）的输出还被 ' +
        dep.map((x) => '#' + x + '（' + opNameOf(x) + '）').join('、') + ' 用着，得先删它们' };
    }
  }
  const keep = [];
  let cnt = 0;
  for (const o of opList) {
    if (del.has(o.id)) { disposeOp(o); cnt++; } else keep.push(o);
  }
  opList = keep;
