  const old = nLayer.matBuf.array, oldC = nLayer.colBuf.array;
  layerResize(nLayer, cap);
  nLayer.matBuf.array.set(old.subarray(0, Math.min(G.n * 16, old.length)));
  nLayer.colBuf.array.set(oldC.subarray(0, Math.min(G.n * 3, oldC.length)));
  nLayer.matBuf.needsUpdate = true;
  nLayer.colBuf.needsUpdate = true;
  neuronMesh = nLayer.host;
  const oldSel = selMesh;
  selMesh = makeInstanced(selGeo, selMat, Math.max(1024, cap), false);
  selMesh.instanceMatrix.array.set(oldSel.instanceMatrix.array.subarray(0, Math.min(oldSel.count * 16, oldSel.instanceMatrix.array.length)));
  selMesh.count = oldSel.count;
  selMesh.instanceMatrix.needsUpdate = true;
