  if (nSel === undefined) { const sc = selectionCount(); nSel = sc.n; eSel = sc.e; }
  const s = !!VIEW.sizeByWeight && nSel > 0;
  const w = !!VIEW.widthByWeight && eSel > 0;
  if (s === viewSizeSelOnly && w === viewWidthSelOnly) return false;
  viewSizeSelOnly = s; viewWidthSelOnly = w;
