/* 把界面上那四种「接口」写法归一成数字。认不出来就抛，绝不静默当成"无"。 */
function ioValue(v) {
  if (typeof v === 'number' && v >= 0 && v <= 3) return v | 0;
  const k = String(v == null ? '' : v).trim().toLowerCase();
  if (k === '' || k === 'none' || k === '0' || k === '无' || k === '没有') return IO_NONE;
  if (k === 'in' || k === '1' || k === 'input' || k === '入' || k === '收' || k === '输入' || k === '外界输入') return IO_IN;
  if (k === 'out' || k === '2' || k === 'output' || k === '出' || k === '发' || k === '输出' || k === '输出外界') return IO_OUT;
  if (k === 'both' || k === '3' || k === '双' || k === '双向') return IO_BOTH;
  throw new Error('认不出「' + v + '」是哪种接口。能填的：none / in（接收外界信号）/ out（输出到外界）/ both（双向），或者 0~3。');
}
function setIOBatch(nodes, io) {
  io = ioValue(io);
  for (const i of nodes) nIO[i] = io;
  afterNodeParamChange(nodes); markDirty(); refreshIOPanel();
  toast('已把 ' + nodes.length + ' 个神经元设为「' + IO_LABEL[io] + '」');
}
/* ---- 颜色 ---- */
/* 色号有两套写法：字符串版给人看（右侧面板 / 搜索 / region_map），数字版给「按神经元扫一遍」
   的循环用。底色是量化过的 8 位 sRGB，getHex() 直接把它打包成一个 24 位整数当键——跟
   getHexString() 是同一套取整（three 里就是 ('000000' + getHex().toString(16)).slice(-6)），
   所以数字键和字符串色号一一对应，Map 的分桶跟以前完全一样。
   为什么要数字版：按区认区那几条路（regionHistogram / regionBoxes / geoComponents /
   cellsOfRegion）都是「每个神经元取一次色号」，写成 hexOf(i) 就是每个神经元白扔一个字符串——
   14.4 万神经元跑一趟就是十几万个临时字符串，既费时间又喂垃圾回收。 */
