    recurrent: recE.length > 0, recSteps: REC.steps, numRecEdges: recE.length,
    recSrc: rsrc, recDst: rdst, recW: rw, recLock: rFrozen, rptr: rptr,
    sccCount: rec ? rec.sccSize.length : 0,
