  L.push('');
  L.push('    def _op(self, oi, h, b, t):');
  L.push('        """算子节点（算子级聚合块）：读更早的神经元或更早算子的输出，');
  L.push('        算完把结果写进它的落点神经元。落点神经元不参与波次里的加权求和——');
  L.push('        它们的值完全由这里写入（跟外部输入接口同一个道理）。');
  L.push('        """');
  m.ops.forEach((o, i) => {
    L.push((i ? '        elif ' : '        if ') + 'oi == ' + i + ':');
    L.push('            t[' + o.id + '] = ' + opExpr(i) + '   # ' + o.op + ' ' + o.name);
    if (o.land) {
      L.push('            h = torch.scatter(h, 1, self.' + opLandName(i) +
             '.unsqueeze(0).expand(b, -1), t[' + o.id + '].reshape(b, -1))');
    }
  });
  L.push('        else:');
