  const count = nn.io ? nn.io.length : nn.kind.length;
  ensureNeuronCapacity(count + 8);
  ensureEdgeCapacity(o.edges.length + 8);
  G.n = count; G.e = 0; G.name = o.name || '未命名工程';
  G.source = o.source || null;   /* v2 格式里没有这一段，载入就等于「没有来源表」 */
  G.pid = o.pid || '';
  seedRand(o.seed === undefined ? DEF_SEED : o.seed);
  clearBlocks(); selBlocks.clear();   /* 旧工程的块不能留下来 */
  if (o.blocks && o.blocks.length) {
    for (const b of o.blocks) {
      try {
        makeBlock(b.src, b.dst, Float32Array.from(b.w), {
          lock: b.lock ? Uint8Array.from(b.lock) : null, label: b.label || '', sg: b.sg | 0,
        });
      } catch (err) { console.warn('权重块读不进来，已跳过：' + err.message); }
    }
    /* JSON 里每块都带了自己那份 w，但同一个 sg 的块语义上是**同一个参数**，
       所以这里统一成第一份——不然"共享组"名不副实（改一处改不到另一处）。 */
    blockShareGroups().forEach((mem) => {
      const w = blocks[mem[0]].w;
      for (let t = 1; t < mem.length; t++) blocks[mem[t]].w = w;
    });
  }
  clearOps();
  if (o.ops && o.ops.length) {
    for (const r of o.ops) {
      try {
        makeOp(r.op, r.name, {
          id: r.id, ins: r.ins, outShape: r.outShape, land: r.land,
          attrs: r.attrs, fold: r.fold, note: r.note, color: r.color, colOn: r.colOn, pos: r.pos,
          params: (r.params || []).map((p) => ({ name: p.name, dtype: p.dtype, shape: p.shape, data: p.data })),
        });
      } catch (err) { console.warn('算子节点读不进来，已跳过：' + err.message); }
    }
  }
  nPos.set(nn.pos.slice(0, count * 3));
  if (nn.io) nIO.set(nn.io);
  else for (let i = 0; i < count; i++) nIO[i] = nn.kind[i] === 0 ? IO_IN : nn.kind[i] === 2 ? IO_OUT : IO_NONE;
  nColOn.fill(0, 0, count); nCol.fill(0, 0, count * 3); nThr.fill(DEF_THR, 0, count);
  if (nn.col) nCol.set(nn.col.slice(0, count * 3));
  if (nn.colOn) nColOn.set(nn.colOn);
  if (nn.thr) nThr.set(nn.thr);
  nAct.set(nn.act); nBias.set(nn.bias); nLock.set(nn.lock);
  nName.clear();
  for (const k in nn.names) nName.set(parseInt(k, 10), nn.names[k]);
  /* 分组：老工程没有这一段，读不到就是「没有分组」。真正的成员关系在 G.gsets，
     multi（一个神经元同时在好几个组）是后加的：没有就按主分组退化重建。 */
  G.groups = (o.groups && Array.isArray(o.groups.list)) ? o.groups.list.slice() : [];
  nGroup.fill(0);
  if (o.groups && o.groups.of) {
    for (const k in o.groups.of) {
      const i = parseInt(k, 10), g = o.groups.of[k] | 0;
      if (i >= 0 && i < count && g > 0 && g <= G.groups.length) nGroup[i] = g;
    }
  }
  G.gsets = [];
  for (let g = 0; g < G.groups.length; g++) G.gsets.push({ a: new Uint32Array(0) });
  if (o.groups && Array.isArray(o.groups.multi)) { groupApplyMultiDoc(o.groups.multi, count); gsyncPrimary(); }
  else groupRebuildFromPrimary();
  /* 手动隐藏：老工程没有这一段 -> 什么都没藏 */
  nHid.fill(0, 0, count);
  if (o.hidden && Array.isArray(o.hidden.n)) {
    for (let k = 0; k < o.hidden.n.length; k++) { const i = o.hidden.n[k] | 0; if (i >= 0 && i < count) nHid[i] = 1; }
  }
  rebuildAdjacency();
  histEdgeDirty = 1; histWDirty = 1;
  for (const e of o.edges) {
    const k = G.e++;
    eSrc[k] = e[0]; eDst[k] = e[1]; eW[k] = e[2]; eLock[k] = e[3]; eHid[k] = 0; eId[k] = edgeSeq++;
  }
  if (o.hidden && Array.isArray(o.hidden.e)) {
    for (let k = 0; k < o.hidden.e.length; k++) { const e = o.hidden.e[k] | 0; if (e >= 0 && e < G.e) eHid[e] = 1; }
  }
  rebuildAdjacency(); rebuildScene(); clearSelection();
  resetHistory(); refreshAll(); updateProjName();
  /* 可塑性：档位表 + 稀疏的「谁用哪一档」。老工程没这一段 -> 全部按固定不学习。 */
  nPlast.fill(0, 0, count); nHard.fill(0, 0, count);
