    if (sx > 0) { t = Math.floor((nPos[i * 3] - x0) / sx * Q); qx = t < 0 ? 0 : (t > Q ? Q : t); }
    if (sy > 0) { t = Math.floor((nPos[i * 3 + 1] - y0) / sy * Q); qy = t < 0 ? 0 : (t > Q ? Q : t); }
    if (sz > 0) { t = Math.floor((nPos[i * 3 + 2] - z0) / sz * Q); qz = t < 0 ? 0 : (t > Q ? Q : t); }
    code[i] = nf3Morton3(qx, qy, qz);
