    if (act === 'chan-on') { c.on = el.checked; if (c.on && IFACE.on) ifaceChanOpen(c, true); if (!c.on) ifaceChanClose(c, true); renderIfacePanel(); return; }
    if (act === 'chan-name') { c.name = el.value.trim() || ('通道 ' + c.id); return; }
