  /* 相机：方向盘 + 聚焦 / 居中 + 跟随开关 */
  /* 方向盘：按住就持续滑行（pointer capture 保证指针拖出按钮也一直走），
     快速点一下 = 一小段平滑位移 + 缓停，跟按住方向键是同一条路径。 */
  const bindPanBtn = (id, dx, dy) => {
    const el = $('#' + id);
    if (!el) return;
    const start = (e) => {
      e.preventDefault();
      el.classList.add('on');
      panHold(dx, dy, true, e.shiftKey);
      try { el.setPointerCapture(e.pointerId); } catch (err) { /* 老浏览器不支持就算了 */ }
    };
    const stop = () => { if (!el.classList.contains('on')) return; el.classList.remove('on'); panHold(dx, dy, false); };
    el.addEventListener('pointerdown', start);
    el.addEventListener('pointerup', stop);
    el.addEventListener('pointercancel', stop);
    el.addEventListener('lostpointercapture', stop);
  };
  bindPanBtn('cam-up', 0, 1);
  bindPanBtn('cam-down', 0, -1);
  bindPanBtn('cam-left', -1, 0);
  bindPanBtn('cam-right', 1, 0);
  /* "镜头对着空白"提示里的一键找回 */
  const vhF = $('#vh-focus'); if (vhF) vhF.addEventListener('click', () => frameWholeGraph());
  const vhH = $('#vh-home'); if (vhH) vhH.addEventListener('click', () => resetView());
  $('#cam-home').addEventListener('click', () => resetView());
