  $('#cam-center').addEventListener('click', () => centerOnSelection());
  $('#cam-follow').addEventListener('change', (e) => setCamFollow(e.target.checked));
$('#v-dim').addEventListener('change', (e) => { focusDim = e.target.checked; syncFocusDim(); requestRender(); });
/* 视觉缩放：两个开关 + 两个对比度滑杆。
   滑杆拖动时只重写"受影响的那一层"（大小 -> 球层，粗细 -> 圆柱层），
   松手（change）再来一次完整重建，保证分块剔除、选中壳这些跟着对齐。 */
function syncGainRows() {
  const rows = [['r-wwidth', VIEW.widthByWeight, 'v-wgain', VIEW.widthGain, 'v-wgain-v'],
                ['r-wsize', VIEW.sizeByWeight, 'v-sgain', VIEW.sizeGain, 'v-sgain-v']];
  for (let k = 0; k < rows.length; k++) {
    const rowId = rows[k][0], on = rows[k][1], inId = rows[k][2], val = rows[k][3], labId = rows[k][4];
    const row = document.getElementById(rowId), inp = document.getElementById(inId), lab = document.getElementById(labId);
    if (row) row.classList.toggle('off', !on);
    if (inp) { inp.disabled = !on; if (Number(inp.value) !== Number(val)) inp.value = String(val); }
    if (lab) lab.textContent = Number(val).toFixed(1) + '×';
  }
}
/* 拖动滑杆时的即时反馈：只重算受影响的那一层，不等松手。
   规模大的时候每一帧重写几十万个实例不合算（一次就是几 MB 上传），
   这种规模的图上改成松手（change）后一次做完，提示里会说清楚。 */
const LIVE_RESCALE_MAX = 40000;
function liveRescaleOff() { return Math.max(nBuilt, cBuilt) > LIVE_RESCALE_MAX; }
function rescaleNeuronsNow() {
  if (!(builtMask & LAYER_N)) {
    if (LOD.tier === 'low') rebuildFarLayer();   /* 简档下"大小"画在点云上 */
    requestRender(); return;
  }
  if (liveRescaleOff()) { requestRender(); return; }
  beginBatch();
  for (let i = 0; i < nBuilt; i++) writeNeuronInstance(i);
  endBatch();
  rebuildSelMesh();
  requestRender();
}
function rescaleEdgesNow() {
  if (!(builtMask & LAYER_CYL)) { requestRender(); return; }
  if (liveRescaleOff()) { requestRender(); return; }
  beginBatch();
  for (let e = 0; e < cBuilt; e++) writeEdgeCylinder(e, true, true);
  endBatch();
  requestRender();
}
$('#v-wsize').addEventListener('change', (e) => { VIEW.sizeByWeight = e.target.checked; viewStatsTouch(); syncGainRows(); refreshViewScale(); });
$('#v-wwidth').addEventListener('change', (e) => { VIEW.widthByWeight = e.target.checked; refreshViewGains(); viewStatsTouch(); syncGainRows(); refreshViewScale(); });
$('#v-sgain').addEventListener('input', (e) => { VIEW.sizeGain = gainOf(e.target.value); viewStatsTouch(); syncGainRows(); rescaleNeuronsNow(); updateViewScaleHint(); });
$('#v-wgain').addEventListener('input', (e) => { VIEW.widthGain = gainOf(e.target.value); refreshViewGains(); viewStatsTouch(); syncGainRows(); rescaleEdgesNow(); updateViewScaleHint(); });
$('#v-sgain').addEventListener('change', (e) => { VIEW.sizeGain = gainOf(e.target.value); viewStatsTouch(); syncGainRows(); refreshViewScale(); });
$('#v-wgain').addEventListener('change', (e) => { VIEW.widthGain = gainOf(e.target.value); refreshViewGains(); viewStatsTouch(); syncGainRows(); refreshViewScale(); });

/* ---- 权重阈值：只画够强的连接（解决「千万级连线糊成一团」）----------------
   滑杆的行程走立方曲线：权重分布是长尾的（这个工程 p50=0.07、p90=0.135、
   p99=2），线性滑杆会把有用的区间全挤在最左边几个像素里。位置 t 对应
   阈值 = ref·t³，ref 取 p99.9；旁边的数字实时显示真实阈值，下面那句
   「大约还剩百分之几的连接」也是实算的，所以曲线不会造成误导。
   大数据层改阈值只是换一个 uniform：零重建、立刻生效；
   老两条路（圆柱 / 细线）把粗细 / 端点烘进了缓冲，只能重写一遍，
   所以规模大时拖动只更新数字，松手（change）才整体重写。 */
function wMinRef() { const r = wAbsQuantile(0.999); return r > 1e-9 ? r : 1; }
function wMinFromPos(t) { return t <= 0 ? 0 : wMinRef() * t * t * t; }
function wMinPosFrom(v) { if (!(v > 0)) return 0; return Math.min(1, Math.cbrt(v / wMinRef())); }
function setEdgeWMinUI(v) {
  const m = Number(v);
  VIEW.wMin = isFinite(m) && m > 0 ? m : 0;
  syncWMinRows(); updateWMinHint(); applyWFilterNow(true);
  return VIEW.wMin;
}
function applyWFilterNow(full) {
  bigSyncUniforms();   /* 阈值的本体是 uniform：会话里立刻刷上去，不等下一帧 */
  if (BIG.on) { requestRender(); return; }   /* 大数据层：uniform 一改就生效，零重建 */
  if (!full && liveRescaleOff()) { requestRender(); return; }
  beginBatch();
  if (builtMask & LAYER_CYL) for (let e = 0; e < cBuilt; e++) writeEdgeCylinder(e, true, true);
  if (builtMask & LAYER_LINE) for (let e = 0; e < lBuilt; e++) writeEdgeLine(e, true);
  endBatch();
  if (LOD.tier === 'low') rebuildFarLayer();
  requestRender();
}
function syncWMinRows() {
  const on = VIEW.wMin > 0;
  const row = document.getElementById('r-wmin'), inp = document.getElementById('v-wmin');
  const box = document.getElementById('v-wmin-on'), lab = document.getElementById('v-wmin-v');
  if (row) row.classList.toggle('off', !on);
  if (box) box.checked = on;
  if (inp) inp.disabled = !on;
  if (lab) lab.textContent = on ? num(VIEW.wMin) : '关';
}
function updateWMinHint() {
  const el = document.getElementById('wmin-hint');
  if (!el) return;
  const h = wAbsHist();
  if (!(h.cnt > 0)) { el.textContent = '当前没有连接，阈值无从谈起。'; return; }
  const head = '连接权重实测（|w|）：最大 ' + num(h.max) + '，p50 ' + num(wAbsQuantile(0.5))
    + '，p90 ' + num(wAbsQuantile(0.9)) + '，p99 ' + num(wAbsQuantile(0.99)) + '。';
  if (!(VIEW.wMin > 0)) { el.textContent = head + '现在不过滤，全部连接都画。'; return; }
  const pct = wAbsFraction(VIEW.wMin) * 100;
  el.textContent = head + '现在只画 |w| ≥ ' + num(VIEW.wMin) + ' 的连接：大约还剩 '
    + (pct >= 10 ? pct.toFixed(0) : pct.toFixed(1)) + '%（约 ' + fmt(Math.round(pct * G.e / 100)) + ' 条）。'
    + '选中的 / 高亮的连接不受影响；大数据层改阈值是零重建、立刻生效，'
    + '老两条路线要重写一遍缓冲，规模大时松手才整体刷新。';
}
if (document.getElementById('v-wmin-on')) {
  document.getElementById('v-wmin-on').addEventListener('change', (ev) => {
    wMinAutoChecked = true;   /* 在面板上动过手了：这次会话不再自动开 */
    const inp = document.getElementById('v-wmin');
    if (ev.target.checked) {
      const t = inp ? Number(inp.value) / 1000 : 0;
      VIEW.wMin = wMinFromPos(t > 0.01 ? t : 0.62);
      if (inp) inp.value = String(Math.round(wMinPosFrom(VIEW.wMin) * 1000));
    } else VIEW.wMin = 0;
    syncWMinRows(); updateWMinHint(); applyWFilterNow(true);
    wMinUserSet(VIEW.wMin);
  });
  document.getElementById('v-wmin').addEventListener('input', (ev) => {
    wMinAutoChecked = true;   /* 在面板上动过手了：这次会话不再自动开 */
    VIEW.wMin = wMinFromPos(Number(ev.target.value) / 1000);
    syncWMinRows(); updateWMinHint(); applyWFilterNow(false);
  });
  document.getElementById('v-wmin').addEventListener('change', (ev) => {
    wMinAutoChecked = true;   /* 在面板上动过手了：这次会话不再自动开 */
    VIEW.wMin = wMinFromPos(Number(ev.target.value) / 1000);
    syncWMinRows(); updateWMinHint(); applyWFilterNow(true);
    wMinUserSet(VIEW.wMin);
  });
  const presets = [['v-wmin-p50', 0.5], ['v-wmin-p90', 0.9], ['v-wmin-p99', 0.99]];
  for (const pr of presets) {
    const b = document.getElementById(pr[0]);
    if (!b) continue;
    b.addEventListener('click', () => {
    wMinAutoChecked = true;   /* 在面板上动过手了：这次会话不再自动开 */
      VIEW.wMin = wAbsQuantile(pr[1]);
      const inp = document.getElementById('v-wmin');
      if (inp) inp.value = String(Math.round(wMinPosFrom(VIEW.wMin) * 1000));
      syncWMinRows(); updateWMinHint(); applyWFilterNow(true);
      wMinUserSet(VIEW.wMin);
    });
    b.title = '阈值设成 |w| 的 p' + Math.round(pr[1] * 100) + ' 分位（实算，采样近似）';
  }
  const clr = document.getElementById('v-wmin-clear');
  if (clr) clr.addEventListener('click', () => {
    wMinAutoChecked = true;   /* 在面板上动过手了：这次会话不再自动开 */
    VIEW.wMin = 0;
    const inp = document.getElementById('v-wmin');
    if (inp) inp.value = '0';
    syncWMinRows(); updateWMinHint(); applyWFilterNow(true);
    wMinUserSet(VIEW.wMin);
  });
  syncWMinRows();
}
