  const base = AI.visBase || AI.base, model = AI.visModel || AI.model, key = AI.visKey || AI.key;
  if (!base || !model || !key) return null;
  if (!base || !model || (!key && !aiIsLocal(base))) return null;
  const own = !!(AI.visBase || AI.visModel);
