        const out = await aiExec(c.name, c.args);
        aiPush({ role: 'tool', text: c.name + ' ' + aiShortArgs(c.args) + ' → ' + aiBrief(out) });
        if (native) AI.msgs.push({ role: 'tool', tool_call_id: c.id, content: aiJson(out) });
